import six
import os
from logging import FileHandler
from ute_ue.lteuepool import CfgFileBasedUePool
from ute_ue.exceptions import RequiredUeNotFound
from ute_common_abstract_core.exceptions import InvalidConfigurationContent
from ute_common_abstract_core.logger import AbstractLibLogger
from ta_ue_plugin_rtg.rtg_ue import RtgUe
from ta_ue_plugin_rtg.uecap_utils import ParametrizedUeCapabilities
from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall
from ta_ue_plugin_rtg.rpc.uex_connection import UexConnection
from ta_ue_plugin_rtg.rtg_ue_group import RtgUeGroup
import logging


class RtgUePool(CfgFileBasedUePool):
    """Rtg Ue Pool"""

    def __init__(self, config_file_path=None, inline_config=None):
        """Basic initialization."""
        super(RtgUePool, self).__init__(config_file_path, inline_config)

        self.ue_list = []
        self.ue_cap_map = None
        if 'UE_CAPABILITIES_MAP' in self._device_configuration:
            self.ue_cap_map = self._device_configuration['UE_CAPABILITIES_MAP']

        uex_conn = UexConnection()
        self.rpc_conn = uex_conn.rpc_conn

        self.rpc_call = RpcCall(self.rpc_conn, self.logger).call

        # atexit.register(self.server.cancel())

    def _get_device(self, device_characteristics, create_msg_src_id=True):
        """Create RtgUe instance and append it to the ue_list"""
        ue_cap_list = self._get_uecap_list(device_characteristics.domain_capabilities)
        starting_cell = device_characteristics.starting_cell

        if isinstance(starting_cell, six.string_types):
            starting_cell = int(starting_cell, 0)

        params = {"starting_cell": starting_cell, "ue_cap_list": ue_cap_list}
        ue_id = self.rpc_call(method="get_device", params=params, log_msg="Get device")
        ue = RtgUe(name="ue" + str(ue_id), rpc_socket=self.rpc_conn, ue_id=ue_id, create_msg_src_id=create_msg_src_id)
        self.ue_list.append(ue)
        self._rename_ue_inside_taken_devices_dict_if_it_points_on_ue_with_given_id(ue_id)
        super(RtgUePool, self)._withdraw_device_from_available_devices("ue" + str(ue_id), ue)
        return ue

    def _rename_ue_inside_taken_devices_dict_if_it_points_on_ue_with_given_id(self, new_ue_id):
        temp = {}
        for ue_name, ue in self._taken_devices.items():
            if ue.get_ue_id() == new_ue_id:
                temp['{}.old'.format(ue_name)] = ue
            else:
                temp[ue_name] = ue
        self._taken_devices = temp

    def _get_custom_uecap_list(self, capabilities_name):
        ue_capabilities = []
        for one_ue_cap in self._return_list_of_ue_cap_parameters(capabilities_name):  # list of (ue_cap_type, ue_cap_hex, ue_cap_parameters)
            ue_cap_type, ue_cap_hex, ue_cap_parameters = one_ue_cap

            if ue_cap_parameters is not None:
                uecap = ParametrizedUeCapabilities(parameters_dict=ue_cap_parameters)
                ue_cap_hex = uecap.get_hex_value()

            ue_capabilities.append({'type': ue_cap_type, 'hex': ue_cap_hex})
        return ue_capabilities

    def _get_uecap_list(self, capabilities_name):
        ue_capabilities = [{'type': None, 'hex': None}]
        if self.ue_cap_map is not None:
            if capabilities_name is not None:
                if capabilities_name in self.ue_cap_map:
                    ue_capabilities = self._get_custom_uecap_list(capabilities_name)
                else:
                    self.logger.warning("{0} not found inside UE_CAPABILITIES_MAP".format(capabilities_name))
                    raise RequiredUeNotFound("{0} not found inside UE_CAPABILITIES_MAP".format(capabilities_name))
            else:
                self.logger.warning("'capabilities' prameter not specified, will use default UE capabilities")
        else:
            if capabilities_name is not None:
                self.logger.warning("UE_CAPABILITIES_MAP section not found inside configuration")
                raise RequiredUeNotFound("UE_CAPABILITIES_MAP section not found inside configuration")

        return ue_capabilities

    def _return_list_of_ue_cap_parameters(self, capabilities):
        ue_cap_entry = self.ue_cap_map[capabilities]
        if isinstance(ue_cap_entry, list):
            valid_ue_cap = []
            for ue_cap in ue_cap_entry:
                valid_ue_cap.append(self._validate_and_return_ue_cap_parameters(capabilities, ue_cap))
            return valid_ue_cap
        else:
            return [self._validate_and_return_ue_cap_parameters(capabilities, ue_cap_entry)]

    def _get_ue_cap_type(self, capabilities_name, ue_cap):
        if 'ue_cap_type' in ue_cap:
            ue_cap_type = ue_cap['ue_cap_type']
            if ue_cap_type != 'eutra' and ue_cap_type != 'nbiot' and ue_cap_type != 'eutra_nr' and ue_cap_type != 'nr':
                raise InvalidConfigurationContent("ue_cap_type should be either 'eutra' or 'nbiot' or 'eutra_nr' or 'nr'")
            return ue_cap_type
        raise InvalidConfigurationContent("Missing ue_cap_type parameter for {}".format(capabilities_name))

    def _validate_and_return_ue_cap_parameters(self, capabilities_name, ue_cap):
        ue_cap_type = self._get_ue_cap_type(capabilities_name, ue_cap)
        if 'ue_cap_hex' in ue_cap and 'ue_cap_parameters' not in ue_cap:
            ue_cap_hex = ue_cap['ue_cap_hex']
            return ue_cap_type, ue_cap_hex, None
        elif 'ue_cap_parameters' in ue_cap and 'ue_cap_hex' not in ue_cap:
            ue_cap_parameters = ue_cap['ue_cap_parameters']
            return ue_cap_type, None, ue_cap_parameters
        elif 'ue_cap_parameters' not in ue_cap and 'ue_cap_hex' not in ue_cap:
            raise InvalidConfigurationContent("ue_cap_type or ue_cap_parameters field is required for {}".format(capabilities_name))
        elif 'ue_cap_parameters' in ue_cap and 'ue_cap_hex' in ue_cap:
            raise InvalidConfigurationContent("Cannot use both ue_cap_parameters and ue_cap_hex to define {}".format(capabilities_name))
        else:
            raise InvalidConfigurationContent("Incorrect UE capabilities configuration for {}".format(capabilities_name))

    def _release_device(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs. (public API)

        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned from this pool via get_ue()
        :return: None
        """
        # self.ue = ue
        # self.rpc_call(method="release_ue", params=ue._ue_id, log_msg="Release device")
        self.ue_list.remove(ue)
        super(RtgUePool, self)._release_device(ue)

    def get_ue_group(self, ue_characteristics, ues_number):
        """
        Return UE-group instance fulfilling requirements.

        :param ue_characteristics: requirements for UE
        :param ues_number: needed number of UEs with such requirements
        :return: ue group instance
        :raises: :py:class:`ute_ue.exceptions.NotEnoughRequiredUes`: If not enough matching ues found
        """
        taken_ues = []
        ue_cap_list = self._get_uecap_list(ue_characteristics.domain_capabilities)
        starting_cell = ue_characteristics.starting_cell

        if isinstance(starting_cell, six.string_types):
            starting_cell = int(starting_cell, 0)

        params = {"starting_cell": starting_cell, "ue_cap_list": ue_cap_list, "number_of_ues": ues_number}

        ue_id_list = self.rpc_call(method="get_device", params=params, log_msg="Get device")
        try:
            for ue_id in ue_id_list:
                found_ue = RtgUe(name="ue" + str(ue_id), rpc_socket=self.rpc_conn, ue_id=ue_id, create_msg_src_id=False)
                RtgUePool._disable_logger_file_handlers(found_ue)
                taken_ues.append(found_ue)
                self.ue_list.append(found_ue)
                super(RtgUePool, self)._withdraw_device_from_available_devices("ue" + str(ue_id), found_ue)
        except Exception:  # nopep8
            self.rpc_call(method="release_ues_from_id_list", params={'ue_ids_list': ue_id_list}, log_msg="RtgUeGroup.release")
            for ue in taken_ues:
                self.ue_list.remove(ue)
                super(RtgUePool, self)._release_device(ue)
            raise
        else:
            ue_group = RtgUeGroup(ues=taken_ues, rpc_socket=self.rpc_conn)
            return ue_group

    def release_ue_group(self, ue_group):
        """
        Release UEs contained in UE-group into UE pool.

        :param ue_group: UE-group instance
        :return: None
        """
        ue_group.release()
        for ue in ue_group.ues:
            self.ue_list.remove(ue)
            super(RtgUePool, self)._release_device(ue)

    @staticmethod
    def _disable_logger_file_handlers(ue):
        for hdlr in ue.logger.logger.handlers:
            if isinstance(hdlr, FileHandler) and not RtgUePool._is_there_ue_group_logger_with_file_hdlr_pointing(hdlr.baseFilename):
                hdlr.close()
                os.remove(hdlr.baseFilename)

    @staticmethod
    def _is_there_ue_group_logger_with_file_hdlr_pointing(logger_file_path):
        for logger in logging.root.manager.loggerDict.values():
            if isinstance(logger, AbstractLibLogger) and logger.parent.name == 'ute_ue.ue_group':
                for hdlr in logger.handlers:
                    if isinstance(hdlr, FileHandler) and hdlr.baseFilename == logger_file_path:
                        return True
        return False
